    //LOGIN
    $scope.loginSession = function () {

        var loginData = {
            "email": $scope.loginemail,
            "password": $scope.loginpass
        }

        var getData = FoundPawmilyService.toLoginSession(loginData);
        getData.then(function (returnedData) {

            if (returnedData.data.success === true) {

                sessionStorage.setItem("currentUserRole", returnedData.data.role);

                Swal.fire({
                    title: "Login successful!",
                    icon: "success",
                    confirmButtonColor: "#B9375D"
                }).then(() => {
                    window.location.href = "/Main/Dashboard";
                });

            } else {
                Swal.fire({
                    title: "Invalid login!",
                    text: returnedData.data.message,
                    icon: "error",
                    confirmButtonColor: "#B9375D"
                });
            }            
        });
    }

