    $scope.previewPetImage = function (event) {
        var file = event.target.files[0];
        if (!file) return;
        var reader = new FileReader();

        reader.onload = function (e) {
            $scope.petDataEdit.imagePreview = e.target.result;
            $scope.newUploadedImage = file;

            $scope.$apply();
        };

        reader.readAsDataURL(file);
    };

