    $scope.numbersOnly = function (event) {
        if (event.charCode < 48 || event.charCode > 57) {
            event.preventDefault();
        }
    };

    $scope.lettersOnly = function (event) {
        var charCode = event.which || event.keyCode;
        if (
            !(charCode >= 65 && charCode <= 90) &&  // uppercase
            !(charCode >= 97 && charCode <= 122) && // lowercase
            charCode !== 32 &&  // space
            charCode !== 8 &&      // backspace
            charCode !== 45 &&      // hyphen
            charCode !== 46 &&      // period
            charCode !== 164 &&     // enye lowercase
            charCode !== 165      // enye uppercase
        ) {
            event.preventDefault();
        }
    };

    $scope.petPattern = function (event) {
        var charCode = event.which || event.keyCode;
        if (
            !(charCode >= 48 && charCode <= 57) && // numbers
            !(charCode >= 65 && charCode <= 90) &&  // uppercase
            !(charCode >= 97 && charCode <= 122) && // lowercase
            charCode !== 32 &&  // space
            charCode !== 8 &&      // backspace
            charCode !== 45 &&      // hyphen
            charCode !== 44 &&      // comma
            charCode !== 164 &&     // enye lowercase
            charCode !== 165      // enye uppercase
        ) {
            event.preventDefault();
        }
    };


