    $scope.getPetProfile = function () {
        const params = new URLSearchParams(window.location.search);
        const petID = parseInt(params.get("id"));

        var petProfileData = FoundPawmilyService.getPetProfileService(petID);
        petProfileData.then(function (returnedData) {
            const pet = returnedData.data;
            if (pet.birthDate) {
                pet.birthDate = new Date(parseInt(pet.birthDate.substr(6)));
                const birth = new Date(pet.birthDate);
                const today = new Date();
                let age = today.getFullYear() - birth.getFullYear();
                const monthDiff = today.getMonth() - birth.getMonth();

                if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
                    age--;
                }

                pet.age = age;
            }
            $scope.petProfileData = pet;
        });
    }

    $scope.hasSelectedPet = function () {
        return angular.isObject($scope.petProfileData) && Object.keys($scope.petProfileData).length > 0;
    };

